WITH matched_keys AS (SELECT job_title, manager_id FROM employees EXCEPT ALL SELECT job_title, manager_id FROM employees WHERE salary <= 137000), reconciled AS (SELECT s.* FROM employees s JOIN matched_keys k ON s.job_title = k.job_title AND s.manager_id = k.manager_id) SELECT s.id, s.full_name, s.email, s.dept_id, s.job_title, s.salary, s.hire_date, s.level, CASE WHEN full_name RLIKE '^(  Carol Diaz|Grace Kim)$' THEN 'PRIORITY' WHEN full_name RLIKE '^(Alice Wong|bob smith)$' THEN 'GROUP_B' ELSE 'EXTENDED' END AS full_name_zone, (SELECT SUM(e2.salary) FROM employees e2 WHERE e2.dept_id = s.dept_id) AS sum_employee_salary FROM reconciled s ORDER BY full_name_zone DESC NULLS LAST, job_title;
